    Class>> {
    }
    Class "AalProfileQueue (AAL Profile Queue)" as queue <<Information Object Class>> {
    }
    lpu "1" *-- "0..n" profilei: aalProfileInstances
    profilei "1" *-down- "0..n" queue: aalProfileQueues
    }
    @enduml

